-- Datos de prueba: 001_semilla_datos_prueba_nucleo
-- Motor objetivo: Microsoft SQL Server 2017
-- Alcance: únicamente schemas catalogo, rrhh, organizacion e integracion.
-- Propósito: poblar un escenario sintético y repetible para validar el núcleo.
-- No ejecutar contra producción. Requiere las migraciones núcleo 001..008.

SET XACT_ABORT ON;
SET NOCOUNT ON;

IF OBJECT_ID(N'[catalogo].[TipoDocumento]', N'U') IS NULL
   OR OBJECT_ID(N'[rrhh].[JefaturaRelacionLaboral]', N'U') IS NULL
   OR OBJECT_ID(N'[organizacion].[Empresa]', N'U') IS NULL
   OR OBJECT_ID(N'[integracion].[CuentaMicrosoftCorporativa]', N'U') IS NULL
    THROW 51000, N'Faltan tablas del núcleo. Aplique primero las migraciones 001 a 008.', 1;

BEGIN TRANSACTION;

-- Catálogos mínimos para documentos y jefaturas.
IF NOT EXISTS (SELECT 1 FROM [catalogo].[TipoDocumento] WHERE [CodigoTipoDocumento] = N'DNI')
    VALUES (N'DNI', N'Documento nacional de identidad');

IF NOT EXISTS (SELECT 1 FROM [catalogo].[TipoDocumento] WHERE [CodigoTipoDocumento] = N'CE')
    VALUES (N'CE', N'Carné de extranjería');

IF NOT EXISTS (SELECT 1 FROM [catalogo].[TipoJefatura] WHERE [CodigoTipoJefatura] = N'JERARQUICA')
    VALUES (N'JERARQUICA', N'Jefatura jerárquica');

IF NOT EXISTS (SELECT 1 FROM [catalogo].[TipoJefatura] WHERE [CodigoTipoJefatura] = N'FUNCIONAL')
    VALUES (N'FUNCIONAL', N'Jefatura funcional');

-- Maestros organizacionales sintéticos.
IF NOT EXISTS (SELECT 1 FROM [organizacion].[Empresa] WHERE [CodigoEmpresa] = N'03')
    VALUES (N'03', N'Golden Investment S.A.', N'Golden Palace', N'20346662612');

DECLARE @IdEmpresaPrincipal INT = (SELECT [IdEmpresa] FROM [organizacion].[Empresa] WHERE [CodigoEmpresa] = N'03');

IF NOT EXISTS (SELECT 1 FROM [organizacion].[Sede] WHERE [IdEmpresa] = @IdEmpresaPrincipal AND [CodigoSede] = N'01')
    VALUES (@IdEmpresaPrincipal, N'01', N'Golden Palace', N'AV. REPUBLICA DE PANAMA NRO. 3155 LIMA LIMA SAN ISIDRO');

-- Golden Palace: catálogos corporativos autorizados (CSV v3).
-- Fuente: C:\Users\cavalos\Downloads\Data\areas-v3.csv, posiciones-v3.csv, colaborador-v3.csv
DECLARE @Areas TABLE (Id INT, Nombre NVARCHAR(200));
DECLARE @Posiciones TABLE (Id INT, Nombre NVARCHAR(200), IdArea INT);
DECLARE @Colaboradores TABLE (SAP NVARCHAR(50), Documento NVARCHAR(50), ApellidoPaterno NVARCHAR(200), ApellidoMaterno NVARCHAR(200), Nombres NVARCHAR(200), CodigoPosicionSAP NVARCHAR(50), IdPosicion INT, FechaIngreso DATE);
DECLARE @IdTipoDocumentoDniGP SMALLINT = (SELECT [IdTipoDocumento] FROM [catalogo].[TipoDocumento] WHERE [CodigoTipoDocumento] = N'DNI');
DECLARE @IdSedeGoldenPalace INT = (SELECT [IdSede] FROM [organizacion].[Sede] WHERE [IdEmpresa] = @IdEmpresaPrincipal AND [CodigoSede] = N'01');
DECLARE @PersonasNuevasGoldenPalace TABLE
(
    [SAP] NVARCHAR(50) NOT NULL PRIMARY KEY,
    [IdPersona] BIGINT NOT NULL
);

MERGE [rrhh].[Persona] AS [destino]
USING
(
    SELECT [SAP], [Nombres], [ApellidoPaterno], [ApellidoMaterno]
    FROM @Colaboradores AS [origen]
    WHERE NOT EXISTS
    (
        SELECT 1
        FROM [rrhh].[Colaborador] AS [colaborador]
        WHERE [colaborador].[CodigoSAP] = [origen].[SAP]
    )
) AS [origen]
ON 1 = 0
WHEN NOT MATCHED THEN
    INSERT ([Nombres], [ApellidoPaterno], [ApellidoMaterno])
    VALUES ([origen].[Nombres], [origen].[ApellidoPaterno], [origen].[ApellidoMaterno])
OUTPUT [origen].[SAP], INSERTED.[IdPersona]
    INTO @PersonasNuevasGoldenPalace ([SAP], [IdPersona]);

SELECT [persona].[IdPersona], [persona].[SAP]
FROM @PersonasNuevasGoldenPalace AS [persona];

COMMIT TRANSACTION;
GO
