INSERT INTO [organizacion].[Area] ([CodigoArea],[NombreArea],[Descripcion]) SELECT N'GP-AREA-'+CONVERT(NVARCHAR(20),Id),Nombre,N'Área corporativa Golden Palace (CSV v3).' FROM @Areas a WHERE NOT EXISTS (SELECT 1 FROM [organizacion].[Area] x WHERE x.CodigoArea=N'GP-AREA-'+CONVERT(NVARCHAR(20),a.Id));
INSERT INTO [organizacion].[Cargo] ([CodigoCargo],[NombreCargo],[Descripcion]) SELECT N'GP-CARGO-'+CONVERT(NVARCHAR(20),Id),Nombre,N'Cargo corporativo Golden Palace (CSV v3).' FROM @Posiciones p WHERE NOT EXISTS (SELECT 1 FROM [organizacion].[Cargo] x WHERE x.CodigoCargo=N'GP-CARGO-'+CONVERT(NVARCHAR(20),p.Id));
INSERT INTO [rrhh].[Colaborador] ([IdPersona], [CodigoSAP])
INSERT INTO [rrhh].[DocumentoPersona] ([IdPersona],[IdTipoDocumento],[NumeroDocumento],[CodigoPaisEmision],[EsPrincipal],[FechaInicioVigencia]) SELECT z.IdPersona,@IdTipoDocumentoDniGP,c.Documento,N'PE',1,c.FechaIngreso FROM @Colaboradores c JOIN [rrhh].[Colaborador] z ON z.CodigoSAP=c.SAP WHERE NOT EXISTS (SELECT 1 FROM [rrhh].[DocumentoPersona] d WHERE d.IdPersona=z.IdPersona AND d.NumeroDocumento=c.Documento);
INSERT INTO [rrhh].[RelacionLaboral] ([IdColaborador],[IdEmpresa],[FechaInicio]) SELECT z.IdColaborador,@IdEmpresaPrincipal,c.FechaIngreso FROM @Colaboradores c JOIN [rrhh].[Colaborador] z ON z.CodigoSAP=c.SAP WHERE NOT EXISTS (SELECT 1 FROM [rrhh].[RelacionLaboral] r WHERE r.IdColaborador=z.IdColaborador AND r.IdEmpresa=@IdEmpresaPrincipal AND r.FechaInicio=c.FechaIngreso);
INSERT INTO [rrhh].[AsignacionOrganizacional] ([IdRelacionLaboral],[IdSede],[IdArea],[IdCargo],[CodigoPosicionSAP],[FechaInicio],[FechaFin]) SELECT r.IdRelacionLaboral,@IdSedeGoldenPalace,a.IdArea,ca.IdCargo,c.CodigoPosicionSAP,c.FechaIngreso,LEAD(c.FechaIngreso) OVER(PARTITION BY c.SAP ORDER BY c.FechaIngreso,c.IdPosicion) FROM @Colaboradores c JOIN [rrhh].[Colaborador] z ON z.CodigoSAP=c.SAP JOIN [rrhh].[RelacionLaboral] r ON r.IdColaborador=z.IdColaborador AND r.IdEmpresa=@IdEmpresaPrincipal AND r.FechaInicio=c.FechaIngreso JOIN @Posiciones p ON p.Id=c.IdPosicion JOIN [organizacion].[Area] a ON a.CodigoArea=N'GP-AREA-'+CONVERT(NVARCHAR(20),p.IdArea) JOIN [organizacion].[Cargo] ca ON ca.CodigoCargo=N'GP-CARGO-'+CONVERT(NVARCHAR(20),p.Id) WHERE NOT EXISTS (SELECT 1 FROM [rrhh].[AsignacionOrganizacional] q WHERE q.IdRelacionLaboral=r.IdRelacionLaboral AND q.FechaInicio=c.FechaIngreso);
